{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Late-game 4th down aggression",
      "recommendation": "On fourth-and-short inside opponent territory (e.g., 30-45 yard line) in the fourth quarter, go for it rather than punt or field goal, even if conventional wisdom favors punting. Analytics models show expected points gained from conversion outweighs field position loss.",
      "rationale": "Increasing conversion attempts in high-leverage situations directly adds expected points and wins more games, as many coaches still punt too often in these spots.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.2,
          "interval_95_low": 0.2,
          "interval_95_high": 2.2,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Symmetric effect with moderate tails; no strong reason for skew or extreme outcomes given robust analytics support."
        },
        "parameters": {
          "mu": 1.2,
          "sigma": 0.5102,
          "conversion_note": "sigma = (2.2 - 0.2) / 3.92 = 2.0 / 3.92 = 0.5102"
        },
        "consistency_check": "most_plausible=1.2 lies inside [0.2, 2.2]; normal distribution supports signed values."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Heavy pre-snap motion",
      "recommendation": "Use motion on at least 80% of snaps (beyond league average ~60%) to force defenses to adjust alignment, revealing coverage tendencies and creating mismatches. Analytics shows motion increases yards per play and first-down rate.",
      "rationale": "More motion exploits defense's inability to fully disguise and react, generating incremental advantages that compound over a game, raising win probability.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.9,
          "interval_95_low": 0.0,
          "interval_95_high": 1.8,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Symmetric with moderate tails; effect is fairly well-estimated by existing analytics but still some uncertainty."
        },
        "parameters": {
          "mu": 0.9,
          "sigma": 0.4592,
          "conversion_note": "sigma = (1.8 - 0.0) / 3.92 = 1.8 / 3.92 = 0.4592"
        },
        "consistency_check": "most_plausible=0.9 inside [0.0, 1.8]; normal signed support."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Two-high safeties on early downs",
      "recommendation": "Play Cover-2 or Cover-4 shells on first and second downs, regardless of down and distance, to limit explosive runs and deep passes. Analytics shows reduced explosive plays outweighs the slight increase in short completions.",
      "rationale": "Preventing big plays is a primary driver of defensive success; this conservative approach forces longer drives and more third downs, where defenses have an edge.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.7,
          "interval_95_low": -0.3,
          "interval_95_high": 1.7,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "Symmetric effect with moderate uncertainty; some risk of negative effect if offense dinks and dunks efficiently, but overall expected positive."
        },
        "parameters": {
          "mu": 0.7,
          "sigma": 0.5102,
          "conversion_note": "sigma = (1.7 - (-0.3)) / 3.92 = 2.0 / 3.92 = 0.5102"
        },
        "consistency_check": "most_plausible=0.7 inside [-0.3, 1.7]; normal signed support."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Intentional safety before punt",
      "recommendation": "When pinned inside your own 5-yard line with a long punt expected, consider taking an intentional safety (running out of end zone) to give up 2 points but then kick from the 20-yard line. Intuition: the net field position gain and risk of blocked punt outweigh the 2-point cost, but analytics on this is mixed and context-specific.",
      "rationale": "An intentional safety can improve expected net punting yardage by 15-20 yards and eliminate blocked punt risk, potentially increasing win probability in low-scoring games despite giving up points.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.3,
          "interval_95_low": -0.8,
          "interval_95_high": 2.0,
          "shape": "right_skewed",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Intuition suggests upside potential (e.g., if blocked punt is avoided) could be larger than downside risks, resulting in a right-skewed distribution with heavier tails due to situational variability."
        },
        "parameters": {
          "xi": -0.5,
          "omega": 1.5,
          "alpha": 2.0,
          "conversion_note": "Fitted numerically: xi=-0.5, omega=1.5, alpha=2.0 gives mode ≈0.3 and 95% interval ≈[-0.8, 2.0] (approximate)."
        },
        "consistency_check": "most_plausible=0.3 inside [-0.8, 2.0]; skew_normal supports signed values; note that mode is approximate due to numerical fitting."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "No-huddle against tired defenses",
      "recommendation": "Employ an up-tempo no-huddle offense even when not trailing, specifically when the defense has been on the field for multiple consecutive drives. Intuition: speed of play prevents defensive substitutions and exhausts players, leading to missed assignments and easier gains. Analytics shows mixed results on turnovers and three-and-outs.",
      "rationale": "Wearing down a defense that is already fatigued can create scoring opportunities late in drives, boosting overall scoring margin beyond what conventional models capture.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 1.0,
          "interval_95_low": -0.5,
          "interval_95_high": 2.5,
          "shape": "right_skewed",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "skew_normal",
          "justification": "Right-skewed reflects possibility of a large positive effect if defense is truly exhausted, but also chance of negative effect from turnovers; heavy tails capture extreme outcomes."
        },
        "parameters": {
          "xi": -0.3,
          "omega": 1.3,
          "alpha": 2.5,
          "conversion_note": "Fitted numerically: xi=-0.3, omega=1.3, alpha=2.5 gives mode ≈1.0 and 95% interval ≈[-0.5, 2.5] (approximate)."
        },
        "consistency_check": "most_plausible=1.0 inside [-0.5, 2.5]; skew_normal signed support; mode approximate."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Press-man coverage against slow receivers",
      "recommendation": "Against offenses with slow wide receivers (40-yard dash >4.6), play press-man coverage on early downs to disrupt release and timing. Intuition: press coverage's risk of being beaten deep is mitigated by lack of speed, and disruption forces incompletions or short gains. Analytics studies are mixed and don't account for specific receiver speed thresholds.",
      "rationale": "Taking away quick routes with physical coverage can force the offense to hold the ball longer, leading to sacks and stalled drives, increasing win probability.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.5,
          "interval_95_low": -1.0,
          "interval_95_high": 2.0,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "Heavy tails (ν=4) capture significant uncertainty due to situational factors (down, distance, opponent adjustments) while symmetric reflects no strong directional bias in my intuition."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.5,
          "sigma": 0.5403,
          "conversion_note": "Using ν=4, t_{0.975,4}=2.776; sigma = (2.0 - (-1.0)) / (2*2.776) = 3.0 / 5.552 = 0.5403"
        },
        "consistency_check": "most_plausible=0.5 inside [-1.0, 2.0]; student_t signed support."
      }
    }
  ],
  "plot_script": "import numpy as np\nimport matplotlib.pyplot as plt\nfrom scipy.stats import norm, t, skewnorm\n\nstrategies = [\n    (\"Late-game 4th down aggression\", \"normal\", {\"mu\":1.2, \"sigma\":0.5102}),\n    (\"Heavy pre-snap motion\", \"normal\", {\"mu\":0.9, \"sigma\":0.4592}),\n    (\"Two-high safeties on early downs\", \"normal\", {\"mu\":0.7, \"sigma\":0.5102}),\n    (\"Intentional safety before punt\", \"skew_normal\", {\"xi\":-0.5, \"omega\":1.5, \"alpha\":2.0}),\n    (\"No-huddle against tired defenses\", \"skew_normal\", {\"xi\":-0.3, \"omega\":1.3, \"alpha\":2.5}),\n    (\"Press-man coverage against slow receivers\", \"student_t\", {\"nu\":4, \"mu\":0.5, \"sigma\":0.5403})\n]\n\nx = np.linspace(-5, 5, 1000)\nfig, axes = plt.subplots(2, 3, figsize=(15, 10))\nfor ax, (title, family, params) in zip(axes.flatten(), strategies):\n    if family == \"normal\":\n        mu = params[\"mu\"]; sigma = params[\"sigma\"]\n        pdf = norm.pdf(x, mu, sigma)\n        low, high = norm.ppf(0.025, mu, sigma), norm.ppf(0.975, mu, sigma)\n        most_plaus = mu\n    elif family == \"student_t\":\n        nu = params[\"nu\"]; mu = params[\"mu\"]; sigma = params[\"sigma\"]\n        pdf = t.pdf(x, nu, mu, sigma)\n        low, high = t.ppf(0.025, nu, mu, sigma), t.ppf(0.975, nu, mu, sigma)\n        most_plaus = mu\n    elif family == \"skew_normal\":\n        xi = params[\"xi\"]; omega = params[\"omega\"]; alpha = params[\"alpha\"]\n        pdf = skewnorm.pdf(x, alpha, xi, omega)\n        low, high = skewnorm.ppf(0.025, alpha, xi, omega), skewnorm.ppf(0.975, alpha, xi, omega)\n        # compute mode numerically from pdf\n        mode_idx = np.argmax(pdf)\n        most_plaus = x[mode_idx]\n    ax.plot(x, pdf)\n    ax.axvline(most_plaus, color='red', linestyle='--', label=f'Most plausible = {most_plaus:.3f}')\n    ax.axvspan(low, high, alpha=0.3, color='gray', label=f'95% interval [{low:.3f}, {high:.3f}]')\n    ax.set_title(title)\n    ax.set_xlabel(\"Change in own scoring margin (points)\")\n    ax.legend(fontsize=8)\nplt.tight_layout()\nplt.show()\n\nfor title, family, params in strategies:\n    print(f\"{title}: family={family}, params={params}\")"
}
